function singleGroupRow(
    context: StatsBucketContext,
    controls: StatsControls,
    unit: StatsUnit,
    identity: string,
    aggregate: GroupAggregate,
): StatsChartRow {
    const tooltipLines: StatsTooltipLine[] = [
